def handle(args, state, ds):
    status = ds.sync_status()
    if not status.get("drift", False):
        return {"status": "synced", "detail": "all linked accounts up to date"}
    return {"status": "syncing", "detail": status.get("detail", "changes pending")}

def handle(args, state, ds):
    report = ds.consistency_report()
    pending = report.get("pending", 0)
    if pending == 0:
        return {"status": "complete", "remaining": 0}
    return {"status": "in_progress", "remaining": pending}

